package com.oms.inventory.service.impl;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.inventory.service.impl.WarehouseAllocationPlanner.*;

/** Shared read model for no-write preview and authoritative, locked allocation. */
@Service
public class OrderWarehouseAllocationService {
    @Resource private JdbcTemplate jdbc;
    public List<Map<String,Object>> receipts(String company,long channel,String tid){require(company!=null&&company.matches("[A-Za-z0-9_-]{1,50}")&&channel>0&&com.oms.common.util.FulfillmentReference.valid(tid),"订单标识无效");return receipts(jdbc,company.toUpperCase(Locale.ROOT),channel,tid);}
    public List<Map<String,Object>> receiptsBatch(String company,Map<String,Object> command){
        long channel=n(command,"channel_id");require(company!=null&&company.matches("[A-Za-z0-9_-]{1,50}")&&channel>0&&command.get("references") instanceof Collection,"库存来源参数无效");
        Collection<?> raw=(Collection<?>)command.get("references");require(!raw.isEmpty()&&raw.size()<=500,"库存来源须为1至500组");Set<String> references=new TreeSet<>();for(Object value:raw){String reference=String.valueOf(value);require(com.oms.common.util.FulfillmentReference.valid(reference)&&references.add(reference),"库存来源无效或重复");}
        List<Object> args=new ArrayList<>(Arrays.asList(company.toUpperCase(Locale.ROOT),channel));args.addAll(references);
        return jdbc.queryForList("SELECT a.quantity-a.released_quantity quantity,a.quantity original_quantity,a.*,d.platform_oid,b.batch_code FROM oms_order_warehouse_allocation a JOIN oms_order_stock_demand d ON d.company_code=a.company_code AND d.id=a.demand_id JOIN wms_inventory_batch b ON b.company_code=a.company_code AND b.id=a.batch_id AND b.sku_sn=a.sku_sn AND b.store_code=a.store_code WHERE a.company_code=? AND a.channel_id=? AND a.platform_tid IN ("+marks(references)+") AND a.status='OCCUPIED' ORDER BY a.id",args.toArray());
    }
    private static String marks(Collection<?> values){return String.join(",",Collections.nCopies(values.size(),"?"));}
    private List<Map<String,Object>> select(String sql,List<Object> args,boolean locked){return jdbc.queryForList(sql+(locked?" FOR UPDATE":""),args.toArray());}
    private static class Context {String company;long channel,required;List<Map<String,Object>> stores,existing,pending,batches,demands;Set<String> skus;}
    @SuppressWarnings("unchecked") private Context load(String rawCompany,Map<String,Object> command,boolean locked){
        require(rawCompany!=null&&rawCompany.matches("[A-Za-z0-9_-]{1,50}"),"公司无效");Context c=new Context();c.company=rawCompany.toUpperCase(Locale.ROOT);c.channel=n(command,"channel_id");String tid=s(command,"platform_tid");require(c.channel>0&&com.oms.common.util.FulfillmentReference.valid(tid),"订单标识无效");
        require(command.get("lines") instanceof List&&command.get("stores") instanceof List,"分仓明细或允许仓无效");List<Map<String,Object>> expected=(List<Map<String,Object>>)command.get("lines");c.stores=(List<Map<String,Object>>)command.get("stores");require(!expected.isEmpty()&&expected.size()<=500,"完整订单明细须为1至500行");require(!c.stores.isEmpty()&&c.stores.size()<=100,"允许仓须为1至100个");
        Set<String> storeCodes=new TreeSet<>(),owners=new HashSet<>();for(Map<String,Object> store:c.stores){require(!s(store,"store_code").isEmpty()&&storeCodes.add(s(store,"store_code"))&&!s(store,"real_store_code").isEmpty()&&!s(store,"owner_code").isEmpty(),"仓库映射无效或重复");owners.add(s(store,"owner_code"));}require(owners.size()==1,"订单分仓只允许同一货主的仓库");
        c.skus=new TreeSet<>();Map<String,Map<String,Object>> lines=new HashMap<>();for(Map<String,Object> line:expected){require(!s(line,"sku_sn").isEmpty()&&n(line,"quantity")>=0&&lines.put(com.oms.common.util.FulfillmentLineKey.of(line),line)==null,"订单明细无效或重复");c.skus.add(s(line,"sku_sn"));}
        List<Object> skuArgs=new ArrayList<>();skuArgs.add(c.company);skuArgs.addAll(c.skus);require(select("SELECT id FROM oms_inventory WHERE company_code=? AND sku_sn IN ("+marks(c.skus)+") ORDER BY sku_sn",skuArgs,locked).size()==c.skus.size(),"公司SKU库存记录缺失");
        c.demands=select("SELECT * FROM oms_order_stock_demand WHERE company_code=? AND channel_id=? AND platform_tid=? ORDER BY sku_sn,platform_oid",Arrays.asList(c.company,c.channel,tid),locked);require(c.demands.size()==expected.size(),"订单与库存需求明细不一致");
        Map<Long,Map<String,Object>> demands=new HashMap<>();for(Map<String,Object> demand:c.demands){Map<String,Object> line=lines.get(com.oms.common.util.FulfillmentLineKey.of(demand));require(line!=null&&s(line,"sku_sn").equals(s(demand,"sku_sn"))&&n(line,"quantity")==n(demand,"demand_quantity"),"订单与库存需求身份不一致");require(!"CANCELLED".equals(s(demand,"status"))||n(demand,"cancelled_quantity")>0,"订单需求已作废，不能分仓");if(!s(demand,"lucky_sku").isEmpty())line.put("lucky_sku",demand.get("lucky_sku"));else line.remove("lucky_sku");long reserved=n(demand,"reserved_quantity");require(reserved>=0&&reserved<=n(demand,"demand_quantity"),"逻辑预占数量异常");require(n(command,"allow_partial")==1||reserved==n(demand,"demand_quantity")-n(demand,"cancelled_quantity"),"逻辑预占尚未全部完成，且店铺未允许部分发货");c.required=Math.addExact(c.required,n(demand,"demand_quantity")-n(demand,"cancelled_quantity"));demands.put(n(demand,"id"),demand);}
        List<Object> sourceArgs=new ArrayList<>();sourceArgs.add(c.company);sourceArgs.addAll(new TreeSet<>(demands.keySet()));List<Map<String,Object>> sources=select("SELECT * FROM oms_order_stock_source WHERE company_code=? AND reserved=1 AND demand_id IN ("+marks(demands.keySet())+") ORDER BY id",sourceArgs,locked);
        c.existing=receipts(jdbc,c.company,c.channel,tid);Map<Long,Long> occupied=new HashMap<>();Set<Long> sourceIds=new HashSet<>(),lockIds=new TreeSet<>(),luckyIds=new TreeSet<>();for(Map<String,Object> source:sources){sourceIds.add(n(source,"id"));if("LOCK".equals(s(source,"source_type")))lockIds.add(n(source,"source_id"));if("LUCKY".equals(s(source,"source_type")))luckyIds.add(n(source,"source_id"));}
        for(Map<String,Object> receipt:c.existing){require(sourceIds.contains(n(receipt,"stock_source_id"))&&storeCodes.contains(s(receipt,"store_code")),"原分仓结果与当前来源或允许仓配置冲突");occupied.merge(n(receipt,"stock_source_id"),n(receipt,"quantity"),Long::sum);}
        Map<Long,Map<String,Object>> locks=new HashMap<>();Map<Long,Long> claims=new HashMap<>();if(!lockIds.isEmpty()){
            List<Object> args=new ArrayList<>();args.add(c.company);args.add(c.channel);args.addAll(lockIds);
            for(Map<String,Object> row:select("SELECT r.id,r.sku_sn,r.batch_id,r.occupied_quantity,b.store_code,b.zp_lock_number FROM rule_stock_reservation r JOIN wms_inventory_batch b ON b.company_code=r.company_code AND b.id=r.batch_id AND b.sku_sn=r.sku_sn WHERE r.company_code=? AND r.channel_id=? AND r.id IN ("+marks(lockIds)+") ORDER BY r.id",args,locked))locks.put(n(row,"id"),row);
            List<Object> claimArgs=new ArrayList<>();claimArgs.add(c.company);claimArgs.addAll(lockIds);for(Map<String,Object> row:jdbc.queryForList("SELECT source_id,SUM(quantity-outbound_quantity) claims FROM oms_order_stock_source WHERE company_code=? AND source_type='LOCK' AND reserved=1 AND source_id IN ("+marks(lockIds)+") GROUP BY source_id",claimArgs.toArray()))claims.put(n(row,"source_id"),n(row,"claims"));
        }
        Map<Long,Map<String,Object>> lucky=new HashMap<>();Map<Long,Long> luckyClaims=new HashMap<>();if(!luckyIds.isEmpty()){List<Object> argsLucky=new ArrayList<>(Arrays.asList(c.company,c.channel));argsLucky.addAll(luckyIds);for(Map<String,Object> row:select("SELECT r.id,r.sku_sn,r.batch_id,r.occupied_quantity,p.store_code,b.zp_lock_number FROM oms_lucky_source r JOIN oms_lucky_pool p ON p.company_code=r.company_code AND p.id=r.pool_id JOIN wms_inventory_batch b ON b.company_code=r.company_code AND b.id=r.batch_id AND b.sku_sn=r.sku_sn WHERE r.company_code=? AND p.channel_id=? AND r.id IN ("+marks(luckyIds)+") ORDER BY r.id",argsLucky,locked))lucky.put(n(row,"id"),row);List<Object> totalArgs=new ArrayList<>(Collections.singletonList(c.company));totalArgs.addAll(luckyIds);for(Map<String,Object> row:jdbc.queryForList("SELECT source_id,SUM(quantity-outbound_quantity) claims FROM oms_order_stock_source WHERE company_code=? AND source_type='LUCKY' AND reserved=1 AND source_id IN ("+marks(luckyIds)+") GROUP BY source_id",totalArgs.toArray()))luckyClaims.put(n(row,"source_id"),n(row,"claims"));}
        c.pending=new ArrayList<>();Map<Long,Long> reservedTotals=new HashMap<>();for(Map<String,Object> source:sources){Map<String,Object> demand=demands.get(n(source,"demand_id"));require(demand!=null&&s(source,"sku_sn").equals(s(demand,"sku_sn"))&&n(source,"quantity")>0,"逻辑预占来源身份或数量异常");reservedTotals.merge(n(source,"demand_id"),n(source,"quantity"),Long::sum);
            if("LOCK".equals(s(source,"source_type"))){require(storeCodes.contains(s(source,"store_code")),"原渠道锁库仓不在店铺允许仓内，请调整允许仓配置");Map<String,Object> row=locks.get(n(source,"source_id"));require(row!=null&&s(row,"sku_sn").equals(s(source,"sku_sn"))&&s(row,"store_code").equals(s(source,"store_code")),"原渠道锁库批次缺失或仓库不一致");long claimed=claims.getOrDefault(n(source,"source_id"),0L);require(n(row,"occupied_quantity")>=claimed&&n(row,"zp_lock_number")>=claimed,"原渠道锁库占用余额不足");source.put("batch_id",row.get("batch_id"));}
            else if("LUCKY".equals(s(source,"source_type"))){Map<String,Object> held=lucky.get(n(source,"source_id"));long owed=luckyClaims.getOrDefault(n(source,"source_id"),0L);require(held!=null&&s(held,"sku_sn").equals(s(source,"sku_sn"))&&storeCodes.contains(s(held,"store_code"))&&s(held,"store_code").equals(s(source,"store_code"))&&n(held,"occupied_quantity")>=owed&&n(held,"zp_lock_number")>=owed,"福袋原组件仓库或保障余额不一致");source.put("batch_id",held.get("batch_id"));} else require("PUBLIC_EXTRA".equals(s(source,"source_type"))&&n(source,"source_id")==0,"预占来源类型无效");
            long used=occupied.getOrDefault(n(source,"id"),0L);require(used<=n(source,"quantity"),"仓库占用超过逻辑预占来源数量");long left=n(source,"quantity")-used;if(left>0){Map<String,Object> pending=new LinkedHashMap<>(source);pending.put("quantity",left);pending.put("platform_oid",demand.get("platform_oid"));Map<String,Object> identity=lines.get(com.oms.common.util.FulfillmentLineKey.of(demand));if(!s(identity,"refund_block_reason").isEmpty()){require(n(command,"allow_partial")==1,"退款涉及的商品已挂起，店铺未允许部分发货；请先确认退款范围或调整发货规则");continue;}pending.put("lucky_sku",demand.get("lucky_sku"));pending.put("bundle_id",identity.get("bundle_id"));pending.put("component_quantity",identity.get("component_quantity"));c.pending.add(pending);}
        }
        for(Map<String,Object> demand:c.demands)require(reservedTotals.getOrDefault(n(demand,"id"),0L)==n(demand,"reserved_quantity"),"逻辑预占来源缺失或数量不一致，请先核对来源台账");
        List<Object> args=new ArrayList<>(skuArgs);args.addAll(storeCodes);String scope=" WHERE company_code=? AND sku_sn IN ("+marks(c.skus)+") AND store_code IN ("+marks(storeCodes)+")";
        Map<String,Map<String,Object>> totals=new HashMap<>();for(Map<String,Object> stock:select("SELECT store_code,sku_sn,zp_available_number,zp_actual_number,zp_lock_number FROM wms_inventory"+scope+" ORDER BY sku_sn,store_code",args,locked))require(totals.put(key(s(stock,"sku_sn"),s(stock,"store_code")),stock)==null,"仓库SKU汇总记录重复");
        c.batches=select("SELECT id,store_code,sku_sn,zp_available_number available,zp_lock_number,zp_actual_number FROM wms_inventory_batch"+scope+" ORDER BY sku_sn,store_code,id LIMIT 20001",args,locked);require(c.batches.size()<=20000,"候选批次超过单次20000条上限，请缩小允许仓范围后重试");
        Map<String,long[]> sums=new HashMap<>();for(Map<String,Object> batch:c.batches){require(n(batch,"available")>=0&&n(batch,"zp_lock_number")>=0&&n(batch,"zp_actual_number")==n(batch,"available")+n(batch,"zp_lock_number"),"批次实物、可用与占用库存不一致");long[] sum=sums.computeIfAbsent(key(s(batch,"sku_sn"),s(batch,"store_code")),k->new long[2]);sum[0]+=n(batch,"available");sum[1]+=n(batch,"zp_lock_number");}
        for(String sku:c.skus)for(String store:storeCodes){String key=key(sku,store);long[] sum=sums.getOrDefault(key,new long[2]);Map<String,Object> stock=totals.getOrDefault(key,Collections.emptyMap());require(sum[1]==n(stock,"zp_lock_number"),"仓库汇总与批次占用库存不一致");require(sum[0]==n(stock,"zp_available_number"),"仓库汇总与批次可用库存不一致，请先核对库存台账");require(sum[0]+sum[1]==n(stock,"zp_actual_number"),"仓库实物、可用与占用库存不一致");}return c;
    }
    private List<Map<String,Object>> plan(Context c,Map<String,Object> command){return BundleWarehousePlanner.plan(c.pending,c.batches,c.stores,c.existing,c.required,n(command,"allow_multi")==1,n(command,"allow_partial")==1,n(command,"allow_split_sku")==1,command);}
    @Transactional(readOnly=true,timeout=15,isolation=Isolation.REPEATABLE_READ)
    public Map<String,Object> preview(String company,Map<String,Object> command){Context c=load(company,command,false);List<Map<String,Object>> plan=Collections.emptyList();String error="";try{plan=plan(c,command);}catch(IllegalArgumentException e){error=e.getMessage();}return report(c,command,plan,error);}
    private String fingerprint(Context c,List<Map<String,Object>> plan){List<List<Object>> identity=new ArrayList<>();for(List<Map<String,Object>> rows:Arrays.asList(c.existing,plan))for(Map<String,Object> row:rows)identity.add(Arrays.asList(n(row,"id"),n(row,"stock_source_id"),s(row,"sku_sn"),s(row,"owner_code"),s(row,"real_store_code"),s(row,"store_code"),n(row,"batch_id"),n(row,"quantity")));identity.sort(Comparator.comparing(Object::toString));return com.oms.common.util.AllocationDigest.hash(identity);}
    private Map<String,Object> report(Context c,Map<String,Object> command,List<Map<String,Object>> plan,String error){
        Map<String,Object> report=new LinkedHashMap<>();long before=quantity(c.existing),added=quantity(plan);report.put("can_allocate",error.isEmpty()&&added>0);report.put("message",error.isEmpty()?(added>0?"预览通过，确认时将重新校验库存并生成发货单":"已全部分仓，无需重复提交"):error);report.put("required_quantity",c.required);report.put("allocated_quantity",before);report.put("planned_quantity",added);report.put("remaining_quantity",c.required-before-added);report.put("logical_pending_quantity",Math.max(0,c.required-before-quantity(c.pending)));
        Set<Long> mapped=new HashSet<>();if(command.get("mapped_allocation_ids") instanceof Collection)for(Object id:(Collection<?>)command.get("mapped_allocation_ids"))mapped.add(Long.parseLong(id.toString()));Set<String> newStores=new HashSet<>(),allStores=new HashSet<>();for(Map<String,Object> row:c.existing){allStores.add(s(row,"store_code"));if(!mapped.contains(n(row,"id")))newStores.add(s(row,"store_code"));}for(Map<String,Object> row:plan){allStores.add(s(row,"store_code"));newStores.add(s(row,"store_code"));}long recovered=0;for(Map<String,Object> row:c.existing)if(!mapped.contains(n(row,"id")))recovered+=n(row,"quantity");report.put("recovered_quantity",recovered);report.put("can_allocate",error.isEmpty()&&(added>0||recovered>0));if(error.isEmpty()&&recovered>0)report.put("message","已有库存分仓回执，确认时将核对并补建发货单，避免重复占用");report.put("new_shipment_count",newStores.size());report.put("existing_shipment_count",n(command,"existing_shipment_count"));report.put("total_shipment_count",n(command,"existing_shipment_count")+newStores.size());report.put("virtual_warehouse_count",allStores.size());
        List<Map<String,Object>> recoveredLines=new ArrayList<>();for(Map<String,Object> row:c.existing)if(!mapped.contains(n(row,"id")))recoveredLines.add(row);report.put("recovered_lines",recoveredLines);
        Map<String,String> names=new HashMap<>();for(Object item:(List<?>)command.get("lines")){@SuppressWarnings("unchecked") Map<String,Object> row=(Map<String,Object>)item;names.put(com.oms.common.util.FulfillmentLineKey.of(row),s(row,"goods_name"));}Map<Long,Map<String,Object>> demands=new HashMap<>();for(Map<String,Object> row:c.demands)demands.put(n(row,"id"),row);List<Map<String,Object>> lines=new ArrayList<>();for(Map<String,Object> row:plan){Map<String,Object> line=new LinkedHashMap<>(row);line.put("platform_oid",demands.get(n(row,"demand_id")).get("platform_oid"));line.put("goods_name",names.get(com.oms.common.util.FulfillmentLineKey.of(line)));lines.add(line);}report.put("lines",lines);report.put("plan_fingerprint",fingerprint(c,plan));
        Map<String,Long> free=new HashMap<>(),locked=new HashMap<>(),need=new TreeMap<>(),chosen=new HashMap<>();for(Map<String,Object> row:c.batches)free.merge(key(s(row,"sku_sn"),s(row,"store_code")),n(row,"available"),Long::sum);for(Map<String,Object> row:c.pending){need.merge(s(row,"sku_sn"),n(row,"quantity"),Long::sum);if(LuckyBagStock.protectedSource(s(row,"source_type")))locked.merge(key(s(row,"sku_sn"),s(row,"store_code")),n(row,"quantity"),Long::sum);}for(Map<String,Object> row:plan)chosen.merge(s(row,"store_code"),n(row,"quantity"),Long::sum);
        Map<String,Set<String>> fixed=new HashMap<>();if(n(command,"allow_split_sku")==0){for(Map<String,Object> row:c.existing)fixed.computeIfAbsent(s(row,"sku_sn"),k->new HashSet<>()).add(s(row,"store_code"));for(Map<String,Object> row:c.pending)if(LuckyBagStock.protectedSource(s(row,"source_type")))fixed.computeIfAbsent(s(row,"sku_sn"),k->new HashSet<>()).add(s(row,"store_code"));}List<Map<String,Object>> candidates=new ArrayList<>();int rank=0;for(Map<String,Object> store:c.stores){String code=s(store,"store_code");Map<String,Object> item=new LinkedHashMap<>(store);item.put("rank",++rank);item.put("selected_quantity",chosen.getOrDefault(code,0L));List<Map<String,Object>> goods=new ArrayList<>();long covered=0;boolean restricted=false;for(Map.Entry<String,Long> demand:need.entrySet()){String key=key(demand.getKey(),code);long available=free.getOrDefault(key,0L),inherited=locked.getOrDefault(key,0L);Set<String> bound=fixed.getOrDefault(demand.getKey(),Collections.emptySet());String restriction=!bound.isEmpty()&&!(bound.size()==1&&bound.contains(code))?"同SKU来源已固定至 "+String.join("、",new TreeSet<>(bound)):"";restricted|=!restriction.isEmpty();if(restriction.isEmpty())covered+=Math.min(demand.getValue(),available+inherited);if(goods.size()<20){Map<String,Object> good=new LinkedHashMap<>();good.put("sku_sn",demand.getKey());good.put("restriction",restriction);good.put("pending_quantity",demand.getValue());good.put("public_available",available);good.put("inherited_locked",inherited);goods.add(good);}}item.put("goods",goods);item.put("goods_truncated",need.size()>20);item.put("coverage_quantity",covered);
            String reason=chosen.getOrDefault(code,0L)>0?("REGION_FIRST".equals(s(command,"strategy"))?"按区域及默认顺序分配，保留原锁库来源":"优先整单，数量相同时比较新增发货单数及仓库顺序"):covered==0?(restricted?"同SKU原锁库或已有分仓固定在其他虚拟仓":"本单SKU无可用库存或可继承锁库"):covered<quantity(c.pending)?"单仓不足以满足本次全部逻辑预占需求":"其他方案更符合当前策略";
            if(chosen.getOrDefault(code,0L)==0&&n(command,"max_virtual_warehouses")>0&&allStores.size()>=n(command,"max_virtual_warehouses")&&!allStores.contains(code))reason="已达到最多虚拟仓数量上限";
            if(chosen.getOrDefault(code,0L)==0&&n(command,"max_shipments")>0&&n(command,"existing_shipment_count")+newStores.size()>=n(command,"max_shipments")&&!newStores.contains(code))reason="累计发货单名额已用尽";item.put("reason",reason);candidates.add(item);
        }report.put("candidates",candidates);report.put("retry_kind",Boolean.TRUE.equals(report.get("can_allocate"))?"NONE":n(command,"max_shipments")>0&&n(command,"existing_shipment_count")>=n(command,"max_shipments")&&n(report,"recovered_quantity")==0?"MANUAL":"STOCK");return report;
    }
    @Transactional(rollbackFor=Exception.class,timeout=30,isolation=Isolation.READ_COMMITTED)
    public List<Map<String,Object>> allocate(String rawCompany,Map<String,Object> command){Context c=load(rawCompany,command,true);String company=c.company;long channel=c.channel;String tid=s(command,"platform_tid");Set<String> skus=c.skus;List<Map<String,Object>> plan=plan(c,command);
        if(command.containsKey("expected_plan_fingerprint"))require(fingerprint(c,plan).equals(s(command,"expected_plan_fingerprint")),"库存或分仓结果已变化，请重新预览后确认；本次未新增占用");
        for(Map<String,Object> receipt:plan){long qty=n(receipt,"quantity");
            if("PUBLIC_EXTRA".equals(s(receipt,"source_type"))){
                Map<String,Object> before=jdbc.queryForMap("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=?",company,receipt.get("batch_id"));
                require(jdbc.update("UPDATE wms_inventory_batch SET zp_available_number=zp_available_number-?,zp_lock_number=zp_lock_number+?,version=version+1 WHERE company_code=? AND id=? AND zp_available_number>=?",qty,qty,company,receipt.get("batch_id"),qty)==1,"批次库存不足，分仓已回滚");
                require(jdbc.update("UPDATE wms_inventory SET zp_available_number=zp_available_number-?,zp_lock_number=zp_lock_number+?,version=version+1 WHERE company_code=? AND store_code=? AND sku_sn=? AND zp_available_number>=?",qty,qty,company,receipt.get("store_code"),receipt.get("sku_sn"),qty)==1,"仓库库存不足，分仓已回滚");
                journal(jdbc,before,qty,"ORDER_LOCK",channel+"/"+tid);
            }
            jdbc.update("INSERT INTO oms_order_warehouse_allocation(company_code,channel_id,platform_tid,demand_id,stock_source_id,sku_sn,source_type,batch_id,store_code,owner_code,real_store_code,real_store_name,quantity) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",company,channel,tid,receipt.get("demand_id"),receipt.get("stock_source_id"),receipt.get("sku_sn"),receipt.get("source_type"),receipt.get("batch_id"),receipt.get("store_code"),receipt.get("owner_code"),receipt.get("real_store_code"),receipt.get("real_store_name"),qty);
            jdbc.update("INSERT INTO oms_order_stock_event(company_code,demand_id,action,quantity,message) VALUES (?,?,'WAREHOUSE_ALLOCATE',?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity),message=VALUES(message)",company,receipt.get("demand_id"),qty,"分仓至 "+s(receipt,"real_store_code")+" / "+s(receipt,"store_code")+"，"+("LOCK".equals(s(receipt,"source_type"))?"继承渠道锁库":"公共库存转仓库占用"));
        }
        for(String sku:skus)OrderStockService.refresh(jdbc,company,sku,channel);
        return receipts(jdbc,company,channel,tid);
    }
    public static List<Map<String,Object>> receipts(JdbcTemplate jdbc,String company,long channel,String tid){return jdbc.queryForList("SELECT a.quantity-a.released_quantity quantity,a.quantity original_quantity,a.*,d.platform_oid,b.batch_code FROM oms_order_warehouse_allocation a JOIN oms_order_stock_demand d ON d.company_code=a.company_code AND d.id=a.demand_id JOIN wms_inventory_batch b ON b.company_code=a.company_code AND b.id=a.batch_id AND b.sku_sn=a.sku_sn AND b.store_code=a.store_code WHERE a.company_code=? AND a.channel_id=? AND a.platform_tid=? AND a.status='OCCUPIED' ORDER BY a.id",company,channel,tid);}
    /** Called inside logical cancellation's transaction and already-held SKU mutexes. */
    public static void release(JdbcTemplate jdbc,List<Map<String,Object>> demands){
        require(demands.stream().allMatch(d->n(d,"outbound_quantity")==0),"已有出库，不能释放整单仓库占用");
        for(Map<String,Object> demand:demands){String company=s(demand,"company_code");for(Map<String,Object> receipt:jdbc.queryForList("SELECT * FROM oms_order_warehouse_allocation WHERE company_code=? AND demand_id=? AND status='OCCUPIED' ORDER BY id FOR UPDATE",company,demand.get("id"))){long qty=n(receipt,"quantity");
            if("PUBLIC_EXTRA".equals(s(receipt,"source_type"))){
                Map<String,Object> before=jdbc.queryForMap("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=?",company,receipt.get("batch_id"));
                require(jdbc.update("UPDATE wms_inventory_batch SET zp_available_number=zp_available_number+?,zp_lock_number=zp_lock_number-?,version=version+1 WHERE company_code=? AND id=? AND zp_lock_number>=?",qty,qty,company,receipt.get("batch_id"),qty)==1,"原分仓批次占用余额不足，释放已回滚");
                require(jdbc.update("UPDATE wms_inventory SET zp_available_number=zp_available_number+?,zp_lock_number=zp_lock_number-?,version=version+1 WHERE company_code=? AND store_code=? AND sku_sn=? AND zp_lock_number>=?",qty,qty,company,receipt.get("store_code"),receipt.get("sku_sn"),qty)==1,"原分仓仓库占用余额不足，释放已回滚");
                journal(jdbc,before,-qty,"ORDER_UNLOCK",receipt.get("channel_id")+"/"+receipt.get("platform_tid"));
            }
            jdbc.update("UPDATE oms_order_warehouse_allocation SET status='RELEASED' WHERE id=?",receipt.get("id"));
        }}
    }
    static void journal(JdbcTemplate jdbc,Map<String,Object> before,long delta,String operation,String relation){
        Map<String,Object> after=jdbc.queryForMap("SELECT * FROM wms_inventory_batch WHERE id=?",before.get("id"));
        List<Object> args=new ArrayList<>(Arrays.asList(before.get("company_code"),before.get("store_code"),before.get("sku_sn"),before.get("id"),before.get("batch_code"),"ZP",operation,"OA:"+UUID.randomUUID().toString().replace("-",""),relation,delta,"OMS订单分仓占用或作废释放",0,"OMS订单"));
        StringBuilder columns=new StringBuilder("company_code,store_code,sku_sn,batch_id,batch_code,inventory_type,operation_type,request_id,relation_sn,change_quantity,change_reason,operator_id,operator_name");
        for(String key:Arrays.asList("zp_actual_number","cp_actual_number","zp_available_number","cp_available_number","zp_lock_number","cp_lock_number")){columns.append(",old_").append(key).append(",new_").append(key);args.add(before.get(key));args.add(after.get(key));}
        jdbc.update("INSERT INTO wms_inventory_change_history("+columns+") VALUES ("+String.join(",",Collections.nCopies(args.size(),"?"))+")",args.toArray());
    }
}
